### java
```java
import java.util.*;

class Edge {
    int u, w, t;

    Edge(int u, int w, int t) {
        this.u = u;
        this.w = w;
        this.t = t;
    }
}

class Node implements Comparable<Node> {
    long d;
    int u, t;

    Node(long d, int u, int t) {
        this.d = d;
        this.u = u;
        this.t = t;
    }

    @Override
    public int compareTo(Node other) {
        return Long.compare(this.d, other.d);
    }
}

public class Main {
    static final long INF = (long) 1e18;
    static int N;
    static List<Edge>[] g;
    static boolean[][] st;
    static long[][] dist;
    static int[] a;

    static long dijkstra(int s, int ed) {
        for (int i = 0; i < N; i++) {
            dist[i][0] = INF;
            dist[i][1] = INF;
        }
        dist[s][0] = dist[s][1] = 0;

        PriorityQueue<Node> heap = new PriorityQueue<>();
        heap.offer(new Node(0, s, 0));
        heap.offer(new Node(0, s, 1));

        while (!heap.isEmpty()) {
            Node top = heap.poll();
            int u = top.u, t = top.t;
            if (st[u][t]) continue;
            st[u][t] = true;

            for (Edge e : g[u]) {
                int next_u = e.u, next_t = e.t;
                long trans = 0;
                if (next_t != t) {
                    trans = a[u - 1];
                }
                if (dist[next_u][next_t] > dist[u][t] + trans + e.w) {
                    dist[next_u][next_t] = dist[u][t] + trans + e.w;
                    heap.offer(new Node(dist[next_u][next_t], next_u, next_t));
                }
            }
        }
        return Math.min(dist[ed][0], dist[ed][1]);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        N = n + 1;

        a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextInt();
        }

        g = new ArrayList[N];
        for (int i = 0; i < N; i++) {
            g[i] = new ArrayList<>();
        }

        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            int w = scanner.nextInt();
            int t = scanner.nextInt() - 1;
            g[u].add(new Edge(v, w, t));
            g[v].add(new Edge(u, w, t));
        }

        st = new boolean[N][2];
        dist = new long[N][2];

        System.out.println(dijkstra(1, n));
        scanner.close();
    }
}
